CREATE TABLE admins(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'SUPERADMIN',failed INTEGER DEFAULT 0,locked_until INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admin_sessions(id INTEGER PRIMARY KEY,admin_id INTEGER NOT NULL REFERENCES admins(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,csrf TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,icon_url TEXT,short_description TEXT,full_description TEXT,category TEXT,status TEXT NOT NULL DEFAULT 'research' CHECK(status IN('available','in_development','experimental','research')),version TEXT,release_date TEXT,website_url TEXT,docs_url TEXT,github_url TEXT,screenshots TEXT DEFAULT '[]',sort INTEGER DEFAULT 0,published INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applications(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,platform TEXT NOT NULL,kind TEXT DEFAULT 'file',UNIQUE(product_id,platform));
CREATE TABLE app_releases(id INTEGER PRIMARY KEY,application_id INTEGER NOT NULL REFERENCES applications(id) ON DELETE CASCADE,version TEXT NOT NULL,url TEXT NOT NULL,release_date TEXT,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_rel ON app_releases(application_id,active,id);
CREATE TABLE download_events(id INTEGER PRIMARY KEY,product_id INTEGER,release_id INTEGER,platform TEXT,version TEXT,target TEXT,referrer TEXT,user_agent TEXT,ip_hash TEXT,country TEXT,is_unique INTEGER DEFAULT 0,ts INTEGER NOT NULL);
CREATE INDEX ix_dl_ts ON download_events(ts);CREATE INDEX ix_dl_p ON download_events(product_id,platform,version);CREATE INDEX ix_dl_ip ON download_events(ip_hash,release_id,ts);
CREATE TABLE qr_codes(id INTEGER PRIMARY KEY,application_id INTEGER UNIQUE REFERENCES applications(id) ON DELETE CASCADE,regenerated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE exile_log_entries(id INTEGER PRIMARY KEY,date TEXT NOT NULL,title TEXT NOT NULL,description TEXT,category TEXT,image_url TEXT,product_slug TEXT,link_url TEXT,status TEXT,published INTEGER DEFAULT 1);
CREATE TABLE research_entries(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,abstract TEXT,description TEXT,authors TEXT,date TEXT,category TEXT,status TEXT DEFAULT 'research' CHECK(status IN('research','prototype','experimental','published')),link_url TEXT,product_slug TEXT,published INTEGER DEFAULT 1);
CREATE TABLE journal_posts(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,cover_url TEXT,content TEXT,author TEXT,date TEXT,category TEXT,tags TEXT,product_slug TEXT,published INTEGER DEFAULT 0);
CREATE TABLE portfolio(id INTEGER PRIMARY KEY CHECK(id=1),name TEXT,title TEXT,intro TEXT,bio TEXT,skills TEXT DEFAULT '[]',technologies TEXT DEFAULT '[]',experience TEXT DEFAULT '[]',education TEXT DEFAULT '[]',achievements TEXT DEFAULT '[]',publications TEXT DEFAULT '[]',github TEXT,linkedin TEXT,email TEXT,photo_url TEXT);
CREATE TABLE portfolio_projects(id INTEGER PRIMARY KEY,title TEXT NOT NULL,description TEXT,status TEXT,url TEXT,tech TEXT,sort INTEGER DEFAULT 0,published INTEGER DEFAULT 1);
CREATE TABLE links(id INTEGER PRIMARY KEY,label TEXT NOT NULL,url TEXT NOT NULL,type TEXT,product_slug TEXT,location TEXT,active INTEGER DEFAULT 1);
CREATE TABLE media(id INTEGER PRIMARY KEY,label TEXT,url TEXT NOT NULL,alt TEXT,mime TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY,admin_id INTEGER,action TEXT,entity TEXT,entity_id TEXT,meta TEXT,ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE site_settings(key TEXT PRIMARY KEY,value TEXT);
